import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, vec2, sub, length, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color, DirectionalLight } = ctx.THREE;

  const dock = new Group();
  dock.name = 'nav-dock';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labels = items.map((i) => i.text);
  const colors = config.intent?.visualSpec?.colors ?? {};
  const accent = colors.accent ?? '#ff2a38';
  const paper = colors.paper ?? '#e8ecf2';
  const ink = colors.ink ?? '#16161d';
  const surface = colors.surface ?? '#0b0b10';
  const inactiveColor = '#a6adba';

  const railW = 3.6;
  const railH = 0.5;
  const spacing = 0.68;
  const cellW = 0.6;
  const cellH = 0.34;

  // ---------- Backdrop gradient (stages the node) ----------
  const bmat = new MeshBasicNodeMaterial();
  bmat.colorNode = mix(vec3(0.106, 0.106, 0.137), vec3(0.063, 0.063, 0.082), uv().y);
  const backdrop = new Mesh(new PlaneGeometry(7.2, 6.0), bmat);
  backdrop.position.set(0, 0, -2.5);
  dock.add(backdrop);

  // ---------- Local light rig so metal reads on dark stage ----------
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2.2, 1.6, 2.2);
  keyLight.target.position.set(0, 0, 0);
  dock.add(keyLight);
  dock.add(keyLight.target);

  const rimLight = new DirectionalLight(0xffffff, 0.7);
  rimLight.position.set(-2.4, 0.4, -1.8);
  rimLight.target.position.set(0, 0, 0);
  dock.add(rimLight);
  dock.add(rimLight.target);

  const accentRim = new DirectionalLight(new Color(accent), 0.6);
  accentRim.position.set(-1.4, -0.6, 1.5);
  accentRim.target.position.set(0, 0, 0);
  dock.add(accentRim);
  dock.add(accentRim.target);

  // ---------- Contact-shadow plane beneath the rail ----------
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const duv = sub(uv(), vec2(0.5, 0.5));
  const d = length(duv);
  shadowMat.colorNode = vec3(0.0);
  shadowMat.opacityNode = mul(0.35, smoothstep(0.62, 0.0, d));
  const shadow = new Mesh(new PlaneGeometry(railW + 0.6, railH + 0.5), shadowMat);
  shadow.position.set(0, -0.06 - 0.04, -0.06);
  dock.add(shadow);

  // ---------- Machined-metal rail ----------
  const railMat = new MeshStandardNodeMaterial();
  railMat.metalness = 0.5;
  railMat.roughness = 0.55;
  railMat.clearcoat = 0.2;
  railMat.anisotropy = 0.6;
  railMat.anisotropyRotation = 0.0; // brushed along x
  railMat.colorNode = mix(vec3(0.106, 0.106, 0.137), vec3(0.063, 0.063, 0.082), uv().y);

  const railMesh = new Mesh(new BoxGeometry(railW, railH, 0.06), railMat);
  railMesh.position.set(0, 0, 0.15);
  dock.add(railMesh);

  // ---------- Local specular chamfer catching the key ----------
  const chamferMat = new MeshBasicNodeMaterial({ color: new Color('#2a2a32') });
  const chamfer = new Mesh(new BoxGeometry(railW + 0.004, 0.012, 0.062), chamferMat);
  chamfer.position.set(0, railH / 2 + 0.005, 0.15);
  dock.add(chamfer);

  // ---------- Entries & underline bar ----------
  const entries = new Group();
  entries.position.set(0, 0, 0.15);
  dock.add(entries);

  const entriesArr = [];
  const xCenters = [];
  for (let i = 0; i < 5; i++) {
    xCenters.push(-spacing * 2 + i * spacing);
  }

  let activeIndex = labels.findIndex((l) => l.toLowerCase() === 'home');
  if (activeIndex < 0) activeIndex = 0;

  // Underline bar (MeshStandard with emissive so it glows)
  const ulMat = new MeshStandardNodeMaterial();
  ulMat.emissive = new Color(accent);
  ulMat.emissiveIntensity = 1.8;
  ulMat.toneMapped = true;
  const underline = new Mesh(new BoxGeometry(0.28, 0.025, 0.012), ulMat);
  underline.position.set(xCenters[activeIndex], -0.12, 0.04);
  entries.add(underline);

  const fontColorActive = new Color(paper);
  const fontColorInactive = new Color(inactiveColor);
  const fontColorHover = new Color(paper);

  labels.forEach((label, idx) => {
    const cell = new Group();
    cell.position.set(xCenters[idx], 0, 0);
    entries.add(cell);

    // hit area plane (invisible)
    const hitMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.0, depthWrite: false });
    const hit = new Mesh(new PlaneGeometry(cellW, cellH), hitMat);
    hit.position.set(0, 0, 0.0);
    cell.add(hit);

    const isActive = idx === activeIndex;
    const tColor = isActive ? new Color(paper) : new Color(inactiveColor);
    const textMesh = ctx.fontAtlas.createText(label, {
      fontSize: 13,
      color: '#' + tColor.getHexString(),
      align: 'center',
      letterSpacingPx: 0.0,
    });
    if (textMesh.material && textMesh.material.color) {
      textMesh.material.color.copy(tColor);
    }
    textMesh.position.set(0, 0, 0.02);
    cell.add(textMesh);

    cell.userData.entryIndex = idx;
    cell.userData.label = label;
    cell.userData.baseColor = isActive ? new Color(paper).clone() : new Color(inactiveColor).clone();
    cell.userData.active = isActive;

    cell.userData.handlers = {
      click: () => {
        if (cell.userData.active) return;
        setActive(idx, true);
        const target = { HOME: 'hub-home', FEATURES: 'hub-features', COLLECTION: 'hub-collection', PRICING: 'hub-pricing', JOURNAL: 'hub-journal' }[label] ?? 'hub-home';
        ctx.emit('navigate', { to: target });
      },
      pointerover: () => {
        if (cell.userData.active) return;
        if (!textMesh.material) return;
        if (!textMesh.material.color) return;
        gsap.to(textMesh.material.color, {
          r: fontColorHover.r, g: fontColorHover.g, b: fontColorHover.b,
          duration: 0.16, ease: 'power2.out', overwrite: true,
        });
      },
      pointerout: () => {
        if (cell.userData.active) return;
        if (!textMesh.material || !textMesh.material.color) return;
        const base = cell.userData.baseColor;
        gsap.to(textMesh.material.color, {
          r: base.r, g: base.g, b: base.b,
          duration: 0.16, ease: 'power2.inOut', overwrite: true,
        });
      },
      pointerdown: () => {
        gsap.to(cell.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(1.275)', overwrite: true });
        gsap.to(cell.position, { z: -0.03, duration: 0.12, ease: 'power2.out', overwrite: true });
      },
      pointerup: () => {
        gsap.to(cell.scale, { x: 1.0, y: 1.0, duration: 0.18, ease: 'back.out(1.4)', overwrite: true });
        gsap.to(cell.position, { z: 0.0, duration: 0.18, ease: 'power3.out', overwrite: true });
      },
    };

    entriesArr.push({ cell, textMesh, idx, label, hit });
  });

  function setActive(idx, animateX) {
    if (idx === activeIndex && !animateX) return;
    const prev = activeIndex;
    activeIndex = idx;

    // Swap text colors
    entriesArr.forEach(({ cell, textMesh, idx: i }) => {
      const nowActive = i === activeIndex;
      const newColor = nowActive ? fontColorActive : fontColorInactive;
      cell.userData.active = nowActive;
      cell.userData.baseColor = newColor.clone();
      if (textMesh.material && textMesh.material.color) {
        gsap.to(textMesh.material.color, {
          r: newColor.r, g: newColor.g, b: newColor.b,
          duration: 0.2, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)', overwrite: true,
        });
      }
    });

    // Move underline bar x with weighted overshoot
    if (animateX && underlyingTimeline) underlyingTimeline.kill();
    gsap.to(underline.position, {
      x: xCenters[activeIndex],
      duration: 0.26,
      ease: 'back.out(1.04)',
      overwrite: true,
    });
  }

  let underlyingTimeline = null;

  // ---------- Mount: rise-in ----------
  dock.position.y = 0.4;
  dock.userData.activeIndex = activeIndex;
  gsap.killTweensOf(dock.position);
  gsap.to(dock.position, {
    y: 0,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });

  // subtle weighted settle on rail scale after rise
  gsap.fromTo(
    railMesh.scale,
    { x: 1.04, y: 1.04 },
    { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out', delay: 0.55 }
  );

  // ---------- cleanup ----------
  dock.userData.cleanup = () => {
    gsap.killTweensOf(dock.position);
    gsap.killTweensOf(railMesh.scale);
    if (underline) gsap.killTweensOf(underline.position);
    entriesArr.forEach(({ cell, textMesh }) => {
      if (cell) gsap.killTweensOf(cell.scale);
      if (cell) gsap.killTweensOf(cell.position);
      if (textMesh && textMesh.material && textMesh.material.color) gsap.killTweensOf(textMesh.material.color);
    });
    backdrop.geometry.dispose();
    shadow.geometry.dispose();
    railMesh.geometry.dispose();
    chamfer.geometry.dispose();
    underline.geometry.dispose();
    bmat.dispose();
    shadowMat.dispose();
    railMat.dispose();
    chamferMat.dispose();
    ulMat.dispose();
    entriesArr.forEach(({ hit }) => {
      if (hit) {
        hit.geometry.dispose();
        if (hit.material) hit.material.dispose();
      }
    });
    keyLight.target = null;
    rimLight.target = null;
    accentRim.target = null;
  };

  return dock;
}
